CREATE TABLE stocks(symbol TEXT PRIMARY KEY, company_name TEXT NOT NULL, exchange TEXT NOT NULL, sector TEXT, industry TEXT, isin TEXT, updated_at TEXT);
CREATE TABLE ohlcv(id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL, interval TEXT NOT NULL, candle_time TEXT NOT NULL, open REAL NOT NULL, high REAL NOT NULL, low REAL NOT NULL, close REAL NOT NULL, volume INTEGER NOT NULL, source TEXT NOT NULL, retrieved_at TEXT NOT NULL, UNIQUE(symbol,interval,candle_time,source));
CREATE TABLE fundamentals(id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL, period_end TEXT NOT NULL, period_type TEXT NOT NULL, revenue REAL, operating_profit REAL, net_profit REAL, total_assets REAL, total_debt REAL, equity REAL, market_cap REAL, pe REAL, pb REAL, roe REAL, roce REAL, source TEXT NOT NULL, retrieved_at TEXT NOT NULL);
CREATE TABLE shareholding(id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL, period_end TEXT NOT NULL, promoter_pct REAL, fii_pct REAL, dii_pct REAL, public_pct REAL, pledged_pct REAL, source TEXT NOT NULL, retrieved_at TEXT NOT NULL);
